const { expect } = require("chai");
const hre = require("hardhat");
const fs = require("fs");
const path = require("path");

// BLS gateway (EIP-2537, Base) on-chain verification tests.
//
// vectors.json is generated by the tee-node DKG stack
// (apps/tee-node/ext/blscontract/golang): a real Pedersen DKG on BLS12-381
// (kyber v4 / circl), t-of-n threshold signatures over
// hmG1 = MAP_FP_TO_G1(keccak256(...)), and EIP-2537 conversions pre-verified
// against go-ethereum's EIP-2537 precompiles.
//
// All assertions run INSIDE the EVM (SolTest / BaseBLS in transaction mode):
// the OP-spec RPC precompile path on this fork provider is stateful and
// unreliable (eth_call results change with provider history), so we never
// rely on RPC-level precompile outputs.
//
// Run against a Base Sepolia fork (EIP-2537 precompiles live since Isthmus;
// defaults from `npm run test:base`):
//   HH_FORK_URL=https://sepolia.base.org HH_FORK_BLOCK=58171467 \
//   HH_L1_FORK_CHAIN_ID=84532 HH_OP_FORK_ACTIVATIONS="Bedrock:0,Isthmus:0" \
//   npx hardhat test --config hardhat.config.base.js test/BLS.js
describe("BLS gateway (EIP-2537, Base)", function () {
  // vectors.json is owned by tee-node ext/blscontract/vectors; inject the
  // path with BLS_VECTORS_DIR (dir or file), default to the tee-node checkout.
  const vectorsFile = (() => {
    const teeNode =
      process.env.TEE_NODE_DIR ||
      `${process.env.HOME}/work/cathome/workflow/apps/tee-node`;
    const base = path.join(teeNode, "ext", "blscontract", "vectors");
    const env = process.env.BLS_VECTORS_DIR;
    const p = env
      ? fs.existsSync(env) && fs.statSync(env).isDirectory()
        ? path.join(env, "vectors.json")
        : env
      : path.join(base, "vectors.json");
    if (!fs.existsSync(p)) {
      throw new Error(
        `vectors.json not found: ${p} — set BLS_VECTORS_DIR or run go test ./ext/blscontract/golang/ in tee-node`
      );
    }
    return p;
  })();
  const vectors = JSON.parse(fs.readFileSync(vectorsFile, "utf8"));

  let bls;
  let target;
  let targetAddr;
  let sol;
  let deployer;
  let g2gen;

  const FUND = "0x21e19e0c9bab2400000"; // 100 ETH (wei, hex)

  before(async function () {
    // Vectors require the EIP-2537 BLS12-381 precompiles (Base Isthmus /
    // Fusaka). Accept Base mainnet (8453), Base Sepolia (84532), or a local
    // fork of them (chainId 31337 with HH_FORK_URL set).
    const net = await hre.ethers.provider.getNetwork();
    const chainId = Number(net.chainId);
    const baseFork = process.env.HH_FORK_URL ? true : false;
    if (![8453, 84532].includes(chainId) && !(chainId === 31337 && baseFork)) {
      this.skip(); // not Base / Base fork: EIP-2537 precompiles unavailable
    }
  });

  beforeEach(async function () {
    const signers = await hre.ethers.getSigners();
    deployer = signers[0];
    await hre.network.provider.request({
      method: "hardhat_setBalance",
      params: [deployer.address, FUND],
    });

    const BaseBLS = await hre.ethers.getContractFactory("BaseBLS", deployer);
    const MockTarget = await hre.ethers.getContractFactory("MockTarget", deployer);
    const SolTest = await hre.ethers.getContractFactory("SolTest", deployer);

    target = await MockTarget.deploy();
    await target.waitForDeployment();
    targetAddr = await target.getAddress();

    // g2Generator (256B) is the last 256 bytes of every pairing input.
    g2gen = "0x" + vectors.vectors[0].pairingInput.slice(2 + 512 * 2);

    bls = await BaseBLS.deploy(targetAddr, g2gen);
    await bls.waitForDeployment();

    sol = await SolTest.deploy();
    await sol.waitForDeployment();

    // setAggPubkey is onlyTarget: impersonate the target to set it.
    await hre.network.provider.request({
      method: "hardhat_impersonateAccount",
      params: [targetAddr],
    });
    await hre.network.provider.request({
      method: "hardhat_setBalance",
      params: [targetAddr, "0x1000000000000000000"],
    });
    const signer = await hre.ethers.getImpersonatedSigner(targetAddr);
    await (
      await bls.connect(signer).setAggPubkey(vectors.manifest.aggPubkey)
    ).wait();
  });

  // Send a transaction and return its receipt status (0 = reverted).
  async function txStatus(txPromise) {
    try {
      const rc = await (await txPromise).wait();
      return rc.status;
    } catch (e) {
      return 0;
    }
  }

  it("deploy: aggPubkey and g2Generator stored", async function () {
    expect(await bls.aggPubkey()).to.equal(vectors.manifest.aggPubkey);
    expect(await bls.g2Generator()).to.equal(g2gen);
  });

  it("submit-single: threshold signature verifies on-chain and executes target", async function () {
    const v = vectors.vectors.find((x) => x.name === "submit-single");
    expect(v, "submit-single vector").to.not.undefined;
    await bls
      .connect(deployer)
      .submit(v.targetCalldatas[0], v.hmG1, v.negSig);
    expect(await target.lastValue()).to.equal(42n);
    expect(await target.callCount()).to.equal(1n);
  });

  it("batchSubmit: verifies one signature, executes all target calls", async function () {
    const v = vectors.vectors.find((x) => x.name === "batchSubmit-batch");
    expect(v, "batchSubmit-batch vector").to.not.undefined;
    await bls
      .connect(deployer)
      .batchSubmit(v.targetCalldatas, v.hmG1, v.negSig);
    expect(await target.callCount()).to.equal(BigInt(v.targetCalldatas.length));
  });

  it("pairing: good vector verifies inside the EVM (0x0f)", async function () {
    for (const v of vectors.vectors) {
      const status = await txStatus(
        sol.connect(deployer).assertPair(v.pairingInput, true, {
          gasLimit: 3000000,
        })
      );
      expect(status, `${v.name} pairing`).to.equal(1);
    }
  });

  it("map_fp_to_g1: 0x10 reproduces hmG1 (RPC, fresh provider)", async function () {
    // OP-spec 0x10 在本 EDR provider 的 tx/EVM 路径上未实现（返回空），
    // 仅 RPC eth_call 路径在 provider 刚创建时可用；EthBLS.sol._mapFpToG1
    // 依赖 Base 主网 Fusaka 的真实 0x10，不受影响。
    const v = vectors.vectors.find((x) => x.name === "submit-single");
    const fpInput = hre.ethers.AbiCoder.defaultAbiCoder().encode(
      ["uint256", "uint256"],
      [0, v.msgHash]
    );
    const out = await hre.ethers.provider.call({
      to: "0x0000000000000000000000000000000000000010",
      data: fpInput,
    });
    expect(out.length).to.equal(2 + 128 * 2);
    expect(out.toLowerCase()).to.equal(v.hmG1.toLowerCase());
  });

  it("negative: tampered negSig fails pairing (in-EVM)", async function () {
    const v = vectors.vectors.find((x) => x.name === "submit-single");
    const pi = v.pairingInput.slice(2);
    const cut = (a, b) => "0x" + pi.slice(a * 2, b * 2);
    const tamperLast = (hex) =>
      "0x" +
      ((BigInt(hex) ^ 1n).toString(16)).padStart(hex.length - 2, "0");

    const hm = cut(0, 128);
    const pub = cut(128, 384);
    const neg = cut(384, 512);
    const g2 = cut(512, 768);
    for (const [name, input] of Object.entries({
      hmG1: hm,
      aggPubkey: pub,
      negSig: neg,
      g2Generator: g2,
    })) {
      const tampered =
        "0x" +
        (name === "hmG1" ? tamperLast(hm).slice(2) : hm.slice(2)) +
        (name === "aggPubkey" ? tamperLast(pub).slice(2) : pub.slice(2)) +
        (name === "negSig" ? tamperLast(neg).slice(2) : neg.slice(2)) +
        (name === "g2Generator" ? tamperLast(g2).slice(2) : g2.slice(2));
      const status = await txStatus(
        sol.connect(deployer).assertPair(tampered, false, {
          gasLimit: 3000000,
        })
      );
      expect(status, `tampered ${name} must fail pairing`).to.equal(1);
    }
  });

  it("negative: BaseBLS.submit reverts on tampered negSig", async function () {
    const v = vectors.vectors.find((x) => x.name === "submit-single");
    const bad =
      v.negSig.slice(0, -2) +
      ((parseInt(v.negSig.slice(-2), 16) ^ 0x01).toString(16).padStart(2, "0"));
    const status = await txStatus(
      bls.connect(deployer).submit(v.targetCalldatas[0], v.hmG1, bad, {
        gasLimit: 3000000,
      })
    );
    expect(status).to.equal(0);
    expect(await target.callCount()).to.equal(0n);
  });

  it("negative: BaseBLS.submit reverts on tampered hmG1", async function () {
    const v = vectors.vectors.find((x) => x.name === "submit-single");
    const bad =
      v.hmG1.slice(0, -2) +
      ((parseInt(v.hmG1.slice(-2), 16) ^ 0x01).toString(16).padStart(2, "0"));
    const status = await txStatus(
      bls.connect(deployer).submit(v.targetCalldatas[0], bad, v.negSig, {
        gasLimit: 3000000,
      })
    );
    expect(status).to.equal(0);
    expect(await target.callCount()).to.equal(0n);
  });

  it("negative: CallFailed propagates when target reverts", async function () {
    const v = vectors.vectors.find((x) => x.name === "submit-callfail");
    expect(v, "submit-callfail vector").to.not.undefined;
    const status = await txStatus(
      bls.connect(deployer).submit(v.targetCalldatas[0], v.hmG1, v.negSig, {
        gasLimit: 3000000,
      })
    );
    expect(status).to.equal(0);
    expect(await target.callCount()).to.equal(0n);
  });
});
